package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen2Test {

    @Test
    public void testToClass_NullInput() {
        Class<?>[] result = ClassUtils.toClass(null);
        Assert.assertNull("If input is null, return value should be null", result);
    }

    @Test
    public void testToClass_EmptyArray() {
        Object[] input = new Object[0];
        Class<?>[] result = ClassUtils.toClass(input);
        Assert.assertSame("If input is empty, return ArrayUtils.EMPTY_CLASS_ARRAY", ArrayUtils.EMPTY_CLASS_ARRAY, result);
    }

    @Test
    public void testToClass_ValidObjects() {
        Object[] input = new Object[]{
            "a string",
            123,
            1.5,
            true,
            new StringBuilder()
        };

        Class<?>[] expected = new Class<?>[]{
            String.class,
            Integer.class,
            Double.class,
            Boolean.class,
            StringBuilder.class
        };

        Class<?>[] result = ClassUtils.toClass(input);

        Assert.assertNotNull(result);
        Assert.assertEquals("Result array length should match input length", expected.length, result.length);
        for (int i = 0; i < expected.length; i++) {
            Assert.assertEquals("Class at index " + i + " does not match", expected[i], result[i]);
        }
    }

    @Test
    public void testToClass_SingleElement() {
        Object[] input = new Object[]{ null };
        // Note: null.getClass() would throw NullPointerException. 
        // However, based on the provided source code: classes[i] = array[i].getClass();
        // If the array contains a null element, it will throw NPE.
        // Let's test the behavior for a single non-null object.

        Object[] inputVal = new Object[]{ 10L };
        Class<?>[] expected = new Class<?>[]{ Long.class };
        Class<?>[] result = ClassUtils.toClass(inputVal);

        Assert.assertArrayEquals(expected, result);
    }

    @Test(expected = NullPointerException.class)
    public void testToClass_ArrayWithNullElement() {
        // This test ensures we cover the potential NPE path if an element in the array is null
        // as the provided implementation does not check for null elements within the array.
        Object[] input = new Object[]{ "test", null };
        ClassUtils.toClass(input);
    }
}
